const decisionSystem=`你是中文语音通话的话轮裁决器，不负责回复用户。根据当前发言、对话历史、AI当前播报内容及是否正在播报，判断用户的交互意图和是否说完。输入含参考转写，有音频时同时听音频。
只输出一个JSON对象：{"label":"invalid|backchannel|valid|interrupt","complete":true或false,"should_stop":true或false,"reason":"简短中文理由"}。
invalid：噪声、无意义声音或不面向助手的内容。backchannel：不夺取话轮的倾听反馈。valid：面向助手的实质发言或问题。interrupt：要求停止、纠正当前播报、明确抢占话轮。
不要用固定词表或句尾机械判断。同样的“好的”可以是播报期间的附和，也可以是回答问题；“我想预约明天下午三点”是完整请求。结合语义判断是否缺少关键后半句。发言结束不等于语义完整。
is_final=false表示ASR仍在变化，要保守：只有已有语义清楚表明要打断时才should_stop=true，不要因为识别出了几个字就抢话。is_final=true时，实质发言通常需要接管话轮，即使还没说完；附和和无效声音不需要停止播报。
should_stop表示是否应取消当前AI播报；AI未播报时为false。complete表示能否开始回答；纯停止指令也可以complete=true。JSON中的字段为唯一决策依据，不输出解释段落。`;
export function parseDecision(raw){
 const text=String(raw).trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
 const d=JSON.parse(text);
 if(!['invalid','backchannel','valid','interrupt'].includes(d.label)||typeof d.complete!=='boolean'||typeof d.should_stop!=='boolean'||typeof d.reason!=='string')throw new Error('Qwen判断格式异常，请重试。');
 if((d.label==='invalid'||d.label==='backchannel')&&d.should_stop)throw new Error('Qwen判断冲突，请重试。');
 return {...d,reason:d.reason.slice(0,80)};
}
export async function decideTurn(env,input,signal,fetcher=fetch){
 const {audio,...context}=input;
 const content=audio?[{type:'input_audio',input_audio:{data:'data:audio/wav;base64,'+audio,format:'wav'}},{type:'text',text:JSON.stringify(context)}]:JSON.stringify(context);
 const res=await fetcher(env.DASHSCOPE_BASE_URL+'/chat/completions',{method:'POST',signal,headers:{Authorization:'Bearer '+env.DASHSCOPE_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({model:env.BAILIAN_DECISION_MODEL||env.BAILIAN_CHAT_MODEL,messages:[{role:'system',content:decisionSystem},{role:'user',content}],modalities:['text'],stream:true,max_tokens:256})});
 if(!res.ok)throw new Error('Qwen判断服务返回 '+res.status+'，请重试。');
 let result='';for await(const event of sse(res.body)){if(event.error)throw new Error('Qwen判断失败，请重试。');for(const c of event.choices||[])result+=c.delta?.content||c.delta?.audio?.transcript||'';}
 return parseDecision(result);
}
export function wavBase64(frames){
 const n=frames.reduce((a,b)=>a+b.byteLength,0), out=new Uint8Array(n+44),v=new DataView(out.buffer);
 const s=(p,t)=>{for(let i=0;i<t.length;i++)out[p+i]=t.charCodeAt(i);};
 s(0,'RIFF');v.setUint32(4,36+n,true);s(8,'WAVE');s(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,16000,true);v.setUint32(28,32000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);s(36,'data');v.setUint32(40,n,true);
 let p=44;for(const b of frames){out.set(new Uint8Array(b),p);p+=b.byteLength;}
 return bytes64(out);
}
export function bytes64(data){let s='';for(let i=0;i<data.length;i+=8192)s+=String.fromCharCode(...data.subarray(i,i+8192));return btoa(s);}
export async function* sse(body){
 const reader=body.getReader(),decoder=new TextDecoder();let pending='';
 try{while(true){const {value,done}=await reader.read();pending+=done?decoder.decode():decoder.decode(value,{stream:true});let pos;
 while((pos=pending.indexOf('\n'))>=0){const line=pending.slice(0,pos).trim();pending=pending.slice(pos+1);if(line.startsWith('data: ')&&line!=='data: [DONE]')yield JSON.parse(line.slice(6));}
 if(done){if(pending.startsWith('data: ')&&pending.trim()!=='data: [DONE]')yield JSON.parse(pending.slice(6));break;}
 }}finally{reader.releaseLock();}
}
const system='你是一位自然、简洁的中文电话预约助手。用户可以改约、问问题或闲聊。每次回答一到两句，不超过60个汉字。不能假装访问过真实预约系统；需要真实查询时说明这是演示。倾听用户的新要求，不重复开场白。使用自然口语，语速适中。';
export async function call(request,env){
 if(request.headers.get('Upgrade')?.toLowerCase()!=='websocket')return new Response('WebSocket required',{status:426});
 if(request.headers.get('origin')&&request.headers.get('origin')!==new URL(request.url).origin)return new Response('Origin mismatch',{status:403});
 if(!env.DASHSCOPE_API_KEY)return new Response('模型服务尚未配置',{status:503});
 const voice=new URL(request.url).searchParams.get('mode')!=='text';
 let upstream=null;
 if(voice){
  const url=env.DASHSCOPE_REALTIME_URL.replace(/^wss:/,'https:')+'?model='+encodeURIComponent(env.BAILIAN_ASR_MODEL);
  const res=await fetch(url,{headers:{Upgrade:'websocket',Authorization:'Bearer '+env.DASHSCOPE_API_KEY}});
  if(!res.webSocket)return new Response('实时转写连接失败（'+res.status+'）',{status:502});
  upstream=res.webSocket;
 }
 const pair=new WebSocketPair(),client=pair[0],server=pair[1];server.binaryType='arraybuffer';server.accept();
 let stopped=false,ready=!voice,begun=false,speaking=false,busy=null,generation=0,replies=0,received=0,utteranceStart=0,speechAt=0;
 let frames=[],history=[],pendingText='',pendingFrames=[],resumeTimer,assistantText='',utteranceWasSpeaking=false;
 let decisionAbort=null,decisionEpoch=0,partialBusy=false,lastPartialAt=0,partialStopped=false,inputVersion=0;
 const turnRequests=new Map();
 const cancelTurns=()=>{for(const item of turnRequests.values()){clearTimeout(item.timer);item.resolve(null);}turnRequests.clear();};
 const requestTurn=audio=>new Promise(resolve=>{const id=crypto.randomUUID(),timer=setTimeout(()=>{turnRequests.delete(id);resolve({error:'语句判断超时，请重试。'});},20000);turnRequests.set(id,{resolve,timer});send({type:'turn.request',id,audio});});
 const cancelDecision=()=>{decisionEpoch++;decisionAbort?.abort();decisionAbort=null;};
 const send=o=>{if(!stopped)try{server.send(JSON.stringify(o));}catch{close();}};
 const close=()=>{if(stopped)return;stopped=true;clearTimeout(lifetime);clearTimeout(resumeTimer);cancelDecision();cancelTurns();busy?.abort();try{upstream?.close(1000,'结束通话');}catch{}try{server.close(1000,'结束通话');}catch{}};
 const lifetime=setTimeout(()=>{send({type:'limit',message:'本次体验已满3分钟，请重新接通。'});close();},180000);
 const stop=reason=>{generation++;busy?.abort();busy=null;speaking=false;clearTimeout(resumeTimer);send({type:'action',action:'stop',reason});};
 async function respond(text,audio,opening=false){
  if(stopped)return;
  if(++replies>16){send({type:'limit',message:'本次体验已达16轮，请重新接通。'});close();return;}
  stop('准备回复');speaking=true;assistantText='';
  const own=generation,abort=new AbortController();busy=abort;
  const timer=setTimeout(()=>abort.abort(),40000);
  send({type:'assistant.start',generation:own});
  const user=opening?'请说：您好，我是预约助手，您可以告诉我想修改的预约时间。':text;
  const content=audio?[{type:'input_audio',input_audio:{data:'data:audio/wav;base64,'+audio,format:'wav'}},{type:'text',text:'用户当前发言的参考转写：'+user+'。请结合声音和对话作出简短回应。'}]:user;
  let answer='',audioReceived=false;
  try{
   const res=await fetch(env.DASHSCOPE_BASE_URL+'/chat/completions',{method:'POST',signal:abort.signal,headers:{Authorization:'Bearer '+env.DASHSCOPE_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({model:env.BAILIAN_CHAT_MODEL,messages:[{role:'system',content:system},...history.slice(-10),{role:'user',content}],modalities:['text','audio'],audio:{voice:'Tina',format:'wav'},stream:true,max_tokens:256,stream_options:{include_usage:true}})});
   if(!res.ok){const err=await res.json().catch(()=>({}));throw new Error('对话服务返回 '+res.status+'（'+String(err.error?.code||err.code||'请求失败')+'）');}
   for await(const event of sse(res.body)){
    if(stopped||generation!==own)break;
    if(event.error)throw new Error('对话生成失败');
    for(const choice of event.choices||[]){const d=choice.delta||{};const part=d.audio?.transcript||d.content||'';if(part){answer+=part;assistantText=answer;send({type:'assistant.delta',generation:own,text:part});}if(d.audio?.data){audioReceived=true;send({type:'audio',generation:own,data:d.audio.data,sample_rate:24000});}}
    if(event.usage)send({type:'usage',input_tokens:event.usage.prompt_tokens,output_tokens:event.usage.completion_tokens});
   }
   if(generation===own&&!stopped){if(!audioReceived)throw new Error('模型没有返回语音，请重试。');history.push({role:'user',content:user},{role:'assistant',content:answer});history=history.slice(-10);send({type:'assistant.done',generation:own,text:answer});}
  }catch(err){if(generation===own&&!stopped){speaking=false;send({type:'error',message:err.name==='AbortError'?'回复超时，请再试一次。':String(err.message).slice(0,150)});}}
  finally{clearTimeout(timer);if(generation===own)busy=null;}
 }
 const utteranceAudio=()=>frames.filter(f=>f.start+f.bytes.byteLength/32>=utteranceStart).map(f=>f.bytes);
 async function judge(text,final,audio){
  cancelDecision();const epoch=decisionEpoch,abort=new AbortController();decisionAbort=abort;
  const timer=setTimeout(()=>abort.abort(),15000);
  try{
   const d=await decideTurn(env,{text,pending_text:pendingText,history:history.slice(-8),assistant_speaking:speaking||utteranceWasSpeaking,assistant_text:assistantText,is_final:final,audio},abort.signal);
   if(stopped||epoch!==decisionEpoch)return null;
   send({type:'decision',...d,final,model:env.BAILIAN_DECISION_MODEL||env.BAILIAN_CHAT_MODEL});return d;
  }catch(err){if(!stopped&&epoch===decisionEpoch){send({type:'error',message:err.name==='AbortError'?'Qwen判断超时，请再说一次。':String(err.message).slice(0,140)});if(speaking)stop('判断失败，等待重新发言');}return null;}
  finally{clearTimeout(timer);if(epoch===decisionEpoch)decisionAbort=null;}
 }
 async function complete(text,typed=false){
  clearTimeout(resumeTimer);send({type:'transcript.final',text});
  const version=inputVersion,audioFrames=typed?[]:utteranceAudio(),clip=voice&&!typed?wavBase64([...pendingFrames,...audioFrames].slice(-180)):null;
  const [d,endpoint]=await Promise.all([judge(text,true,clip),clip?requestTurn(clip):null]);
  if(!d||stopped||version!==inputVersion)return;
  if(d.label==='invalid'||d.label==='backchannel'){
   if(speaking)send({type:'action',action:'resume',reason:d.label==='backchannel'?'Qwen判为附和，继续播报':'Qwen判为无效，继续播报'});
   else send({type:'action',action:'listen',reason:'AI 正在听'});
   return;
  }
  if(d.should_stop&&speaking)stop('Qwen：'+d.reason);
  if(clip){
   if(!endpoint||endpoint.error){stop('语句判断未完成');send({type:'error',message:endpoint?.error||'语句判断取消，请重新发言。'});return;}
   send({type:'endpoint',...endpoint});
   if(endpoint.label==='invalid'){send({type:'action',action:'listen',reason:'等待有效发言'});return;}
   d.complete=endpoint.label==='complete';
  }
  if(!d.complete){pendingText+=(pendingText?'，':'')+text;pendingFrames.push(...audioFrames);pendingFrames=pendingFrames.slice(-180);send({type:'action',action:'wait',reason:'等你继续说完'});return;}
  if(speaking&&!d.should_stop){send({type:'action',action:'resume',reason:'Qwen判断保持当前播报'});return;}
  const words=pendingText+(pendingText?'，':'')+text;pendingText='';pendingFrames=[];respond(words,clip);
 }
 async function partial(text){
  if(!speaking||partialBusy||partialStopped||Date.now()-lastPartialAt<900||!text.trim())return;
  partialBusy=true;lastPartialAt=Date.now();
  try{const d=await judge(text,false,null);if(d?.should_stop&&speaking){partialStopped=true;stop('Qwen：'+d.reason);}}finally{partialBusy=false;}
 }
 if(upstream){
  upstream.addEventListener('message',ev=>{
   try{const e=JSON.parse(ev.data);
    if(e.type==='session.created')return;
    else if(e.type==='session.updated'){ready=true;send({type:'ready',chat_model:env.BAILIAN_CHAT_MODEL,asr_model:env.BAILIAN_ASR_MODEL});}
    else if(e.type==='input_audio_buffer.speech_started'){
     inputVersion++;cancelDecision();cancelTurns();speechAt=Date.now();utteranceStart=Math.max(0,received-400);utteranceWasSpeaking=speaking;partialStopped=false;clearTimeout(resumeTimer);
     if(speaking)send({type:'action',action:'pause',reason:'正在听你说'});
    }else if(e.type==='conversation.item.input_audio_transcription.text'){
     const text=(e.text||'')+(e.stash||'');send({type:'transcript.partial',text});
     partial(text);
    }else if(e.type==='conversation.item.input_audio_transcription.completed')complete(e.transcript||e.text||'');
    else if(e.type==='error'){send({type:'error',message:'实时转写错误：'+String(e.error?.code||'请求失败')});close();}
   }catch{send({type:'error',message:'实时转写数据解析失败'});close();}
  });
  upstream.addEventListener('close',()=>{if(!stopped){send({type:'error',message:'实时转写已断开，请重新接通。'});close();}});
  upstream.addEventListener('error',close);upstream.accept();
  upstream.send(JSON.stringify({event_id:crypto.randomUUID(),type:'session.update',session:{modalities:['text'],input_audio_format:'pcm',sample_rate:16000,input_audio_transcription:{language:'zh'},turn_detection:{type:'server_vad',threshold:0.2,silence_duration_ms:500}}}));
 }else send({type:'ready',chat_model:env.BAILIAN_CHAT_MODEL,asr_model:null});
 server.addEventListener('message',ev=>{
  if(stopped)return;
  if(typeof ev.data==='string'){
   let m;try{m=JSON.parse(ev.data);}catch{return;}
   if(m.type==='begin'&&ready&&!begun){begun=true;respond('',null,true);}
   else if(m.type==='text'&&begun&&typeof m.text==='string'&&m.text.trim()){inputVersion++;cancelTurns();utteranceWasSpeaking=speaking;complete(m.text.trim().slice(0,300),true);}
   else if(m.type==='turn.result'&&turnRequests.has(m.id)){
    const item=turnRequests.get(m.id);turnRequests.delete(m.id);clearTimeout(item.timer);
    const probs=m.probabilities,labels=['complete','incomplete','invalid'];
    const valid=labels.includes(m.label)&&probs&&labels.every(k=>typeof probs[k]==='number'&&Number.isFinite(probs[k])&&probs[k]>=0&&probs[k]<=1)&&Math.abs(labels.reduce((a,k)=>a+probs[k],0)-1)<.01;
    item.resolve(valid?{label:m.label,probabilities:probs,model:'TurnSense1.0-INT8',elapsed_ms:Number.isFinite(m.elapsed_ms)?m.elapsed_ms:null}:{error:'语句判断失败，请重试。'});
   }
   else if(m.type==='playback.finished'&&m.generation===generation){speaking=false;send({type:'action',action:'listen',reason:'AI 正在听'});}
   else if(m.type==='stop'){inputVersion++;cancelTurns();cancelDecision();stop('手动停止播报');}
   else if(m.type==='end')close();
  }else if(voice&&ready&&begun){
   const bytes=new Uint8Array(ev.data);if(bytes.length===0||bytes.length>6400||bytes.length%2)return;
   const buffer=bytes.slice().buffer;frames.push({start:received,bytes:buffer});received+=bytes.length/32;while(frames.length&&received-frames[0].start>20000)frames.shift();
   if(received>180000){send({type:'limit',message:'本次体验已满3分钟。'});close();return;}
   upstream.send(JSON.stringify({event_id:crypto.randomUUID(),type:'input_audio_buffer.append',audio:bytes64(bytes)}));
  }
 });
 server.addEventListener('close',close);server.addEventListener('error',close);
 return new Response(null,{status:101,webSocket:client});
}

const HTML="<!doctype html>\r\n<html lang=\"zh-CN\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<meta name=\"theme-color\" content=\"#101619\">\r\n<title>全双工语音通话</title>\r\n<link rel=\"stylesheet\" href=\"/call.css\">\r\n<script src=\"/call.js\" defer></script>\r\n</head>\r\n<body>\r\n<main>\r\n  <header class=\"page-header\">\r\n    <div><h1>全双工语音通话</h1><p>Qwen 语音对话 · 在 AI 说话时直接开口</p></div>\r\n    <a href=\"https://github.com/EEexile/full-duplex-barge-in-demo\">项目与架构 ↗</a>\r\n  </header>\r\n  <div class=\"dashboard\">\r\n    <section class=\"panel signals\" aria-labelledby=\"signal-title\">\r\n      <h2 id=\"signal-title\">当前判断</h2>\r\n      <dl>\r\n        <div><dt>麦克风</dt><dd id=\"mic-state\">未开启</dd></div>\r\n        <div><dt>交互判断</dt><dd id=\"classification\">—</dd></div>\r\n        <div><dt>话轮</dt><dd id=\"turn-state\">—</dd></div>\r\n        <div><dt>播报动作</dt><dd id=\"playback-state\">—</dd></div>\r\n      </dl>\r\n      <details><summary>试说几句</summary>\r\n        <ul>\r\n          <li>「对对对」<span>停一拍，接着说</span></li>\r\n          <li>「我想改一下预约」<span>听清发言后停播</span></li>\r\n          <li>「等一下」<span>识别后停播，让你说</span></li>\r\n          <li>「我想改到……」<span>接着说「明天下午四点」</span></li>\r\n        </ul>\r\n      </details>\r\n      <details class=\"sample-panel\"><summary>听听语句判断示例</summary>\r\n        <p>播放一段示例，看看系统会接话还是等待。</p>\r\n        <button type=\"button\" data-turn-sample=\"complete\">完整表达</button>\r\n        <button type=\"button\" data-turn-sample=\"incomplete\">还没说完</button>\r\n        <button type=\"button\" data-turn-sample=\"invalid\">无效声音</button>\r\n        <p id=\"sample-result\" aria-live=\"polite\"></p>\r\n        <audio id=\"sample-audio\" controls hidden></audio>\r\n      </details>\r\n    </section>\r\n    <section class=\"panel phone\" aria-label=\"预约助手通话\">\r\n      <p class=\"call-name\">预约助手</p>\r\n      <div class=\"orb\" id=\"orb\" data-phase=\"idle\">\r\n        <div class=\"wave\" id=\"wave\" aria-hidden=\"true\"></div>\r\n        <strong id=\"call-state\" role=\"status\">等待接通</strong>\r\n        <time id=\"elapsed\">00:00</time>\r\n      </div>\r\n      <button id=\"call\" class=\"call-button\">\r\n        <svg aria-hidden=\"true\" viewBox=\"0 0 24 24\" width=\"22\" height=\"22\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"><path d=\"M8.1 3.4 5.5 3a2 2 0 0 0-2.2 2.1c.5 7.6 6.6 13.7 14.2 14.2a2 2 0 0 0 2.1-2.2l-.4-2.6a1 1 0 0 0-.7-.8l-3.2-.9a1 1 0 0 0-1 .2l-1.7 1.7a13.4 13.4 0 0 1-5.3-5.3L9 7.7a1 1 0 0 0 .2-1l-.9-3.2Z\"/></svg>\r\n        <span>接通电话</span>\r\n      </button>\r\n      <button id=\"text-call\" class=\"quiet-button\">用文字体验</button>\r\n      <p class=\"note\" id=\"hint\">接通后可直接插话，建议戴耳机。每次体验最多3分钟。</p>\r\n      <form id=\"message\" hidden>\r\n        <label class=\"sr-only\" for=\"message-text\">输入你想说的话</label>\r\n        <input id=\"message-text\" maxlength=\"120\" placeholder=\"输入你想说的话\" autocomplete=\"off\" required>\r\n        <button type=\"submit\">发送</button>\r\n      </form>\r\n      <div class=\"shortcuts\" id=\"shortcuts\" hidden aria-label=\"试说台词\">\r\n        <button type=\"button\">对对对</button><button type=\"button\">等一下</button><button type=\"button\">我想改到</button><button type=\"button\">明天下午四点</button>\r\n      </div>\r\n    </section>\r\n    <section class=\"panel trace\" aria-labelledby=\"trace-title\">\r\n      <h2 id=\"trace-title\">通话事件</h2>\r\n      <p id=\"empty-events\" class=\"empty\">接通后显示判断和播报动作。</p>\r\n      <ol id=\"events\" aria-live=\"polite\" aria-relevant=\"additions\"></ol>\r\n    </section>\r\n    <section class=\"panel conversation\" aria-labelledby=\"conversation-title\">\r\n      <h2 id=\"conversation-title\">通话记录</h2>\r\n      <p id=\"empty-transcript\" class=\"empty\">还没有通话。</p>\r\n      <ol id=\"transcript\" aria-live=\"polite\" aria-relevant=\"additions text\"></ol>\r\n      <p id=\"partial\"></p>\r\n    </section>\r\n  </div>\r\n\r\n</main>\r\n\r\n</body>\r\n</html>\r\n\r\n";
const CLIENT="'use strict';\r\nconst $=id=>document.getElementById(id), names={invalid:'无效',backchannel:'附和',valid:'有效发言',interrupt:'明确打断'};\r\nlet current=null;\r\nlet turnWorker=null,turnReady=null;\r\nconst turnJobs=new Map();\r\nconst sampleJobs=new Map();\r\nfunction loadTurnModel(){\r\n if(!turnReady)turnReady=new Promise((resolve,reject)=>{\r\n  const timer=setTimeout(()=>fail('语音模型加载超时，请刷新后重试。'),120000);\r\n  const fail=message=>{clearTimeout(timer);turnWorker?.terminate();turnWorker=null;turnReady=null;reject(new Error(message));};\r\n  turnWorker=new Worker('/turnsense-worker.mjs',{type:'module'});\r\n  turnWorker.onmessage=({data:m})=>{\r\n   if(m.type==='ready'){clearTimeout(timer);resolve();}\r\n   else if(m.type==='error'&&!m.id)fail('语音模型未能加载：'+m.message);\r\n   else if(m.id&&turnJobs.has(m.id)){const c=turnJobs.get(m.id);turnJobs.delete(m.id);if(current===c)send({type:'turn.result',id:m.id,...(m.type==='result'?{label:m.label,probabilities:m.probabilities,elapsed_ms:m.elapsed_ms}:{error:m.message})});}\r\n   else if(m.id&&sampleJobs.has(m.id)){const job=sampleJobs.get(m.id);sampleJobs.delete(m.id);m.type==='result'?job.resolve(m):job.reject(new Error(m.message));}\r\n  };\r\n  turnWorker.onerror=()=>fail('语音模型未能加载，请刷新后重试。');\r\n  turnWorker.postMessage({type:'init'});\r\n });\r\n return turnReady;\r\n}\r\nfunction state(text,phase='listening'){ $('call-state').textContent=text;$('orb').dataset.phase=phase; }\r\nfunction event(text){if(!current)return;$('empty-events').hidden=true;const li=document.createElement('li');const t=document.createElement('time');t.textContent=$('elapsed').textContent;const s=document.createElement('span');s.textContent=text;li.append(t,s);$('events').append(li);$('events').scrollTop=$('events').scrollHeight;}\r\nfunction line(who,text=''){ $('empty-transcript').hidden=true;const li=document.createElement('li');li.className=who==='你'?'user':'assistant';const small=document.createElement('small');small.textContent=who;const span=document.createElement('span');span.textContent=text;li.append(small,span);$('transcript').append(li);return span; }\r\nfunction send(data){if(current?.ws.readyState===WebSocket.OPEN)current.ws.send(JSON.stringify(data));}\r\nfunction clearPlayback(c){for(const source of c.sources){try{source.stop();}catch{}}c.sources=[];c.nextAt=0;c.done=false;c.generation=null;c.speaking=false;clearInterval(c.finish);c.finish=null;if(c.output.state==='suspended')c.output.resume().catch(()=>{});}\r\nfunction end(reason='通话已结束'){\r\n const c=current;if(!c)return;current=null;for(const [id,owner] of turnJobs)if(owner===c)turnJobs.delete(id);clearInterval(c.clock);clearInterval(c.finish);clearTimeout(c.deadline);clearPlayback(c);c.ws?.close();c.input?.close().catch(()=>{});c.output.close().catch(()=>{});c.stream?.getTracks().forEach(t=>t.stop());$('call').textContent='再次接通';$('text-call').disabled=false;$('message').hidden=true;$('mic-state').textContent='未接通';$('partial').textContent='';state(reason,'idle');\r\n}\r\nfunction play(c,data,rate){\r\n if(!current||current!==c)return;\r\n let raw=Uint8Array.from(atob(data),ch=>ch.charCodeAt(0));\r\n if(raw.length>44&&String.fromCharCode(...raw.subarray(0,4))==='RIFF'){\r\n  const v=new DataView(raw.buffer);let pos=12;\r\n  while(pos+8<=raw.length){const name=String.fromCharCode(...raw.subarray(pos,pos+4)),n=v.getUint32(pos+4,true);if(name==='data'){raw=raw.subarray(pos+8);break;}pos+=8+n+(n%2);}\r\n }\r\n if(raw.length<2)return;const count=Math.floor(raw.length/2),view=new DataView(raw.buffer,raw.byteOffset,raw.byteLength);\r\n const buf=c.output.createBuffer(1,count,rate),dest=buf.getChannelData(0);for(let i=0;i<count;i++)dest[i]=view.getInt16(i*2,true)/32768;\r\n const source=c.output.createBufferSource();source.buffer=buf;source.connect(c.output.destination);c.nextAt=Math.max(c.nextAt,c.output.currentTime+.06);source.start(c.nextAt);c.nextAt+=buf.duration;c.sources.push(source);source.onended=()=>{c.sources=c.sources.filter(s=>s!==source);};c.speaking=true;\r\n}\r\nfunction onMessage(c,m){\r\n if(current!==c)return;\r\n if(m.type==='ready'){\r\n  $('mic-state').textContent=c.mode==='voice'?'麦克风已连接':'文字输入';event('Qwen 服务已连接');state('已接通','listening');c.ready=true;send({type:'begin'});$('message').hidden=false;\r\n }else if(m.type==='turn.request'){\r\n  if(!turnWorker){send({type:'turn.result',id:m.id,error:'语音模型未准备好'});return;}\r\n  turnJobs.set(m.id,c);turnWorker.postMessage({type:'predict',id:m.id,audio:m.audio});\r\n }else if(m.type==='endpoint'){\r\n  const text={complete:'已说完',incomplete:'等待继续',invalid:'等待有效发言'}[m.label];$('turn-state').textContent=text;event('语句判断：'+text);\r\n }else if(m.type==='assistant.start'){\r\n  clearPlayback(c);c.generation=m.generation;c.row=line('AI');state('AI 正在思考','thinking');$('playback-state').textContent='正在生成回复';\r\n }else if(m.type==='assistant.delta'&&m.generation===c.generation){c.row.textContent+=m.text;$('transcript').scrollTop=$('transcript').scrollHeight;}\r\n else if(m.type==='audio'&&m.generation===c.generation){play(c,m.data,m.sample_rate);state('AI 正在说','playing');$('playback-state').textContent='播报中';}\r\n else if(m.type==='assistant.done'&&m.generation===c.generation){\r\n  c.done=true;if(!c.row.textContent)c.row.textContent=m.text;\r\n  const g=m.generation;c.finish=setInterval(()=>{if(current!==c){clearInterval(c.finish);return;}if(c.output.state==='running'&&c.output.currentTime>=c.nextAt-.01){clearInterval(c.finish);c.finish=null;c.speaking=false;send({type:'playback.finished',generation:g});state('AI 正在听');$('playback-state').textContent='播报结束';}},100);\r\n }else if(m.type==='transcript.partial'){$('partial').textContent=m.text;}\r\n else if(m.type==='transcript.final'){ $('partial').textContent='';if(m.text.trim())line('你',m.text);$('classification').textContent='Qwen 判断中';$('turn-state').textContent='判断中'; }\r\n else if(m.type==='decision'){$('classification').textContent=names[m.label]||'—';$('turn-state').textContent=m.complete?'发言完整':'等待继续';event((m.final?'判断：':'识别中：')+(names[m.label]||'—'));}\r\n else if(m.type==='action'){\r\n  if(m.action==='stop'){clearPlayback(c);state(m.reason==='准备回复'?'准备回复':'已停播，正在听');$('playback-state').textContent='已停播';if(m.reason!=='准备回复')event('停止播报，听取新发言');}\r\n  else if(m.action==='pause'){if(c.speaking)c.output.suspend().catch(()=>{});state('正在听你说','hearing');$('playback-state').textContent='短暂停顿';event('听到发言，短暂停顿');}\r\n  else if(m.action==='resume'){c.output.resume().catch(()=>{});state(c.speaking?'AI 接着说':'AI 正在听',c.speaking?'playing':'listening');$('playback-state').textContent=c.speaking?'继续播报':'等待发言';if(c.speaking)event('继续播报');}\r\n  else if(m.action==='wait'){state(m.reason,'hearing');$('turn-state').textContent='等待继续';event('等待你把话说完');}\r\n  else if(m.action==='listen'){state(m.reason);$('turn-state').textContent='等待发言';}\r\n }else if(m.type==='error'){event(m.message);clearPlayback(c);state(m.message,'idle');$('hint').textContent=m.message;}\r\n else if(m.type==='limit'){event(m.message);end(m.message);}\r\n}\r\nasync function start(mode){\r\n if(current){end();return;}\r\n $('sample-audio').pause();\r\n const c={mode,started:performance.now(),ready:false,sources:[],nextAt:0,generation:null,output:new AudioContext(),speaking:false};current=c;\r\n $('hint').textContent='接通后可直接插话，建议戴耳机。每次体验最多三分钟。';$('events').replaceChildren();$('transcript').replaceChildren();$('empty-events').hidden=false;$('empty-transcript').hidden=false;$('partial').textContent='';$('classification').textContent='—';$('turn-state').textContent='等待发言';$('playback-state').textContent='未开始';$('elapsed').textContent='00:00';$('text-call').disabled=true;$('call').textContent='挂断电话';state('正在连接');\r\n try{\r\n  await c.output.resume();\r\n  if(mode==='voice'){\r\n   state('准备语音模型，首次加载稍久','thinking');await loadTurnModel();if(current!==c)return;\r\n   if(!navigator.mediaDevices?.getUserMedia)throw new Error('当前浏览器不支持麦克风，请使用 Chrome 或文字体验。');\r\n   state('请允许麦克风权限');\r\n   const permission=navigator.mediaDevices.getUserMedia({audio:{channelCount:1,echoCancellation:true,noiseSuppression:true,autoGainControl:true}});\r\n   let expired=false,micTimer;\r\n   permission.then(stream=>{if(expired||current!==c)stream.getTracks().forEach(t=>t.stop());},()=>{});\r\n   try{c.stream=await Promise.race([permission,new Promise((_,reject)=>{micTimer=setTimeout(()=>{expired=true;reject(new Error('麦克风授权尚未完成。请允许权限后重新接通，或先用文字体验。'));},15000);})]);}finally{clearTimeout(micTimer);}\r\n   if(current!==c){c.stream.getTracks().forEach(t=>t.stop());return;}\r\n   c.input=new AudioContext();await c.input.audioWorklet.addModule('/capture.js');\r\n   const source=c.input.createMediaStreamSource(c.stream),node=new AudioWorkletNode(c.input,'capture-pcm');const mute=c.input.createGain();mute.gain.value=0;source.connect(node).connect(mute).connect(c.input.destination);await c.input.resume();\r\n   node.port.onmessage=({data})=>{if(current===c&&c.ready&&c.ws.readyState===WebSocket.OPEN){if(c.ws.bufferedAmount>320000){end('网络较慢，请重新接通。');return;}c.ws.send(data);}};\r\n  }\r\n  if(current!==c)return;\r\n  const url=new URL('/api/call',location.href);url.protocol=location.protocol==='https:'?'wss:':'ws:';url.searchParams.set('mode',mode);c.ws=new WebSocket(url);c.ws.onmessage=ev=>{try{onMessage(c,JSON.parse(ev.data));}catch{end('服务返回异常，请重新接通。');}};\r\n  c.ws.onerror=()=>{if(current===c)end('模型连接失败，请重新接通。');};c.ws.onclose=()=>{if(current===c)end('服务已断开，请重新接通。');};\r\n  c.clock=setInterval(()=>{const s=Math.floor((performance.now()-c.started)/1000);$('elapsed').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');},250);\r\n  c.deadline=setTimeout(()=>{if(current===c)end('本次体验已结束，请重新接通。');},181000);\r\n }catch(err){if(current===c)end(err.name==='NotAllowedError'?'请允许麦克风权限，或使用文字体验。':err.message);}\r\n}\r\n$('call').onclick=()=>start('voice');$('text-call').onclick=()=>start('text');\r\n$('message').onsubmit=ev=>{ev.preventDefault();if(!current?.ready)return;const text=$('message-text').value.trim();if(text)send({type:'text',text});$('message-text').value='';};\r\nwindow.addEventListener('pagehide',()=>end());\r\nfor(const button of document.querySelectorAll('[data-turn-sample]'))button.onclick=async()=>{\r\n if(current){$('sample-result').textContent='请先挂断通话，再播放示例。';return;}\r\n const buttons=[...document.querySelectorAll('[data-turn-sample]')];buttons.forEach(b=>b.disabled=true);$('sample-result').textContent='准备语音模型，首次加载稍久…';\r\n try{\r\n  await loadTurnModel();const kind=button.dataset.turnSample,response=await fetch('/turnsense-assets/'+kind+'.wav');if(!response.ok)throw new Error('示例暂不可用');\r\n  const bytes=new Uint8Array(await response.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));\r\n  const id=crypto.randomUUID();$('sample-result').textContent='正在判断…';\r\n  $('sample-audio').src='/turnsense-assets/'+kind+'.wav';$('sample-audio').hidden=false;await $('sample-audio').play();\r\n  const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{sampleJobs.delete(id);reject(new Error('判断超时，请重试。'));},20000);sampleJobs.set(id,{resolve:m=>{clearTimeout(timer);resolve(m);},reject:e=>{clearTimeout(timer);reject(e);}});turnWorker.postMessage({type:'predict',id,audio:btoa(binary)});});\r\n  $('sample-result').textContent={complete:'判断：已说完，可以接话。',incomplete:'判断：还没说完，继续等待。',invalid:'判断：无效声音，暂不接话。'}[result.label];\r\n }catch(error){$('sample-result').textContent=error.message;}finally{buttons.forEach(b=>b.disabled=false);}\r\n};\r\nfor(let i=0;i<19;i++){const bar=document.createElement('i');bar.style.setProperty('--i',i);bar.style.setProperty('--height',(5+i*11%29)+'px');$('wave').append(bar);}\r\n";
const CAPTURE="class CapturePCM extends AudioWorkletProcessor {\r\n constructor(){super();this.data=[];this.frame=Math.round(sampleRate/10);}\r\n process(inputs,outputs){\r\n  const input=inputs[0]?.[0];if(input)for(const sample of input)this.data.push(sample);\r\n  while(this.data.length>=this.frame){const out=new Int16Array(1600);for(let i=0;i<1600;i++){const p=i*sampleRate/16000,a=Math.floor(p),f=p-a;const x=this.data[Math.min(a,this.frame-1)]*(1-f)+this.data[Math.min(a+1,this.frame-1)]*f;out[i]=Math.round(Math.max(-1,Math.min(1,x))*32767);}this.data.splice(0,this.frame);this.port.postMessage(out.buffer,[out.buffer]);}\r\n  for(const channel of outputs[0]||[])channel.fill(0);return true;\r\n }\r\n}\r\nregisterProcessor('capture-pcm',CapturePCM);\r\n";
const TURN_WORKER="import * as ort from '/turnsense-assets/ort.wasm.min.mjs';\nimport {parseCmvn,extractFeatures,pcmFromWav} from '/turnsense-features.mjs';\nconst labels=['complete','incomplete','invalid'];\nlet session,cmvn,loading;\nasync function initialize(){\n if(!loading)loading=(async()=>{\n  ort.env.wasm.numThreads=1;ort.env.wasm.wasmPaths='/turnsense-assets/';\n  const [model,config]=await Promise.all([fetch('/turnsense-assets/model_int8.onnx'),fetch('/turnsense-assets/am.mvn')]);\n  if(!model.ok||!config.ok)throw new Error('语音模型下载失败');\n  const bytes=await model.arrayBuffer();\n  const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');\n  if(hash!=='9ffa8fd0bb423986065afdedcb822fc957bb0794bcb6023c94575d8d82dd8e92')throw new Error('语音模型校验失败');\n  cmvn=parseCmvn(await config.text());\n  session=await ort.InferenceSession.create(bytes,{executionProviders:['wasm']});\n })();\n return loading;\n}\nlet queue=Promise.resolve();\nself.onmessage=({data:m})=>{\n queue=queue.then(async()=>{\n  try{\n   await initialize();\n   if(m.type==='init'){postMessage({type:'ready'});return;}\n   if(m.type!=='predict')return;\n   const started=performance.now(),features=extractFeatures(pcmFromWav(m.audio),cmvn);\n   const outputs=await session.run({feats:new ort.Tensor('float32',features.data,[1,features.length,560]),feat_lengths:new ort.Tensor('int64',BigInt64Array.from([BigInt(features.length)]),[1])});\n   const values=Array.from(Object.values(outputs)[0].data);const sum=values.reduce((a,b)=>a+b,0);\n   const probabilities=values.every(v=>v>=0&&v<=1)&&Math.abs(sum-1)<.0001?values:(()=>{const max=Math.max(...values),e=values.map(v=>Math.exp(v-max)),total=e.reduce((a,b)=>a+b,0);return e.map(v=>v/total);})();\n   if(probabilities.length!==3||probabilities.some(v=>!Number.isFinite(v)))throw new Error('语音模型输出异常');\n   const label=labels[probabilities.indexOf(Math.max(...probabilities))];\n   postMessage({type:'result',id:m.id,label,probabilities:Object.fromEntries(labels.map((k,i)=>[k,probabilities[i]])),elapsed_ms:Math.round(performance.now()-started),model:'TurnSense1.0-INT8'});\n  }catch(error){postMessage({type:'error',id:m.id,message:String(error.message).slice(0,120)});}\n }).catch(()=>{});\n};\n";
const TURN_FEATURES="// Browser port of the published TurnSense AudioFrontend (Apache-2.0).\n// Original: Bairong-Xdynamics/TurnSense, frontend/audio_frontend.py.\n// Modified: implement the same Kaldi Fbank, LFR 7/6 and CMVN in JavaScript.\nconst N=512,BINS=80,FRAME=400,SHIFT=160,EPS=1.1920928955078125e-7;\nconst mel=x=>1127*Math.log1p(x/700);\nconst low=mel(20),high=mel(8000),step=(high-low)/(BINS+1);\nconst filters=Array.from({length:BINS},(_,i)=>Array.from({length:N/2},(_,k)=>{\n const x=mel(k*16000/N),left=low+i*step,center=left+step,right=center+step;\n return Math.fround(x>left&&x<right?(x<=center?(x-left)/step:(right-x)/step):0);\n}));\nconst window=Float64Array.from({length:FRAME},(_,i)=>Math.fround(.54-.46*Math.cos(2*Math.PI*i/(FRAME-1))));\nfunction powerSpectrum(frame){\n const re=new Float64Array(N),im=new Float64Array(N);re.set(frame);\n for(let i=1,j=0;i<N;i++){let bit=N>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)[re[i],re[j]]=[re[j],re[i]];}\n for(let size=2;size<=N;size*=2){const half=size/2;for(let start=0;start<N;start+=size)for(let j=0;j<half;j++){\n  const a=start+j,b=a+half,angle=-2*Math.PI*j/size,c=Math.cos(angle),s=Math.sin(angle),r=re[b]*c-im[b]*s,v=re[b]*s+im[b]*c;\n  re[b]=re[a]-r;im[b]=im[a]-v;re[a]+=r;im[a]+=v;\n }}\n return Float64Array.from({length:N/2},(_,k)=>Math.fround(re[k]*re[k]+im[k]*im[k]));\n}\nexport function parseCmvn(text){\n const lines=text.split(/\\r?\\n/);const rows=[];\n for(let i=0;i<lines.length;i++)if(/^\\s*<(AddShift|Rescale)>/.test(lines[i])){\n  const next=lines[i+1].trim().split(/\\s+/);if(next[0]==='<LearnRateCoef>')rows.push(next.slice(3,-1).map(Number));\n }\n if(rows.length!==2||rows.some(r=>r.length!==560||r.some(v=>!Number.isFinite(v))))throw new Error('TurnSense CMVN格式不匹配');\n return rows;\n}\nexport function extractFeatures(wave,cmvn){\n const audio=wave.length>128000?wave.subarray(wave.length-128000):wave;\n const count=Math.max(0,Math.floor((audio.length-FRAME)/SHIFT)+1);\n if(!count)throw new Error('语音片段过短');\n const frames=[];\n for(let index=0;index<count;index++){\n  const data=new Float32Array(FRAME);let mean=0;\n  for(let i=0;i<FRAME;i++){data[i]=audio[index*SHIFT+i]*32768;mean+=data[i];}mean/=FRAME;\n  for(let i=0;i<FRAME;i++)data[i]=Math.fround(data[i]-mean);\n  for(let i=FRAME-1;i>0;i--)data[i]=Math.fround(data[i]-Math.fround(.97*data[i-1]));data[0]=Math.fround(data[0]-Math.fround(.97*data[0]));\n  for(let i=0;i<FRAME;i++)data[i]=Math.fround(data[i]*window[i]);\n  const power=powerSpectrum(data),feats=new Float32Array(BINS);\n  for(let m=0;m<BINS;m++){let sum=0;for(let k=0;k<N/2;k++)sum+=power[k]*filters[m][k];feats[m]=Math.log(Math.max(EPS,sum));}\n  frames.push(feats);\n }\n const length=Math.ceil(count/6),output=new Float32Array(length*560);\n for(let i=0;i<length;i++)for(let j=0;j<7;j++){\n  const frame=frames[Math.max(0,Math.min(count-1,i*6+j-3))];\n  for(let k=0;k<BINS;k++){const d=j*BINS+k;output[i*560+d]=(frame[k]+cmvn[0][d])*cmvn[1][d];}\n }\n return {data:output,length};\n}\nexport function pcmFromWav(base64){\n const bytes=Uint8Array.from(atob(base64),c=>c.charCodeAt(0)),view=new DataView(bytes.buffer);\n if(bytes.length<44||view.getUint32(24,true)!==16000)throw new Error('需要16kHz PCM音频');\n const count=(bytes.length-44)/2,pcm=new Float32Array(count);\n for(let i=0;i<count;i++)pcm[i]=view.getInt16(44+i*2,true)/32768;\n return pcm;\n}\n";
